module.exports=[62234,a=>{a.v(JSON.parse('{"Navbar":{"home":"Главная","about":"О нас","blog":"Блог","contact":"Контакт","faq":"ЧаВо"},"Hero":{"encrypted":"СКВОЗНОЕ ШИФРОВАНИЕ","title":"Ваша Конфиденциальность, <br></br><span>Одноразовая.</span>","subtitle":"Мгновенно создаваемая безопасная временная почта для анонимного просмотра. <br></br>Без регистрации. Без слежки. Только приватность.","personalize":"Персонализация Адреса","custom_active":"Кастомный Режим: Активен","enter_name":"Введите имя...","create":"Создать","copy":"Копировать","copied":"Скопировано","new":"Новый","new_tooltip":"Создать новый адрес","scan_qr":"Сканировать для Передачи","expiring":"Истекает через","auto_delete":"Письма удаляются через 1 час.","learn_more":"Подробнее об удалении","ad_area":"Рекламная Область"},"Inbox":{"title":"Inbox","waiting":"Ожидание первого письма...","monitoring":"Безопасный мониторинг в реальном времени активен","burn":"Сжечь","burn_tooltip":"Уничтожить этот ящик","sync":"Синх","sync_tooltip":"Восстановить пропущенные письма","block":"Блок","unread":"Непрочитано","code":"Код","close":"Закрыть","are_you_sure":"Вы уверены?","burn_confirm_desc":"Это навсегда удалит адрес и все письма. Это действие нельзя отменить.","cancel":"Отмена","confirm_burn":"Сжечь","block_sender":"Заблокировать отправителя?","block_sender_desc":"Будущие письма от {address} будут молча игнорироваться в текущей сессии."},"Features":{"title":"Архитектура корпоративного уровня","sockets_title":"Сокеты реального времени","sockets_desc":"Обновление не требуется. Письма доставляются мгновенно через безопасные WebSockets.","tls_title":"Шифрование TLS","tls_desc":"Каждое соединение защищено отраслевым стандартом TLS для предотвращения прослушивания.","domain_title":"Мульти-домен","domain_desc":"Обходите фильтры с нашим списком премиальных доменов и поддоменов.","secure_life":"Защитите цифровую жизнь.","secure_desc":"DisposeMail предоставляет мгновенные временные адреса для защиты инбокса от спама и трекеров.","privacy_first":"Приватность прежде всего","no_logs":"Без куки и логов.","zero_cost":"Без оплаты","free_forever":"100% БЕСПЛАТНО ВСЕГДА."},"FAQ":{"title":"Центр помощи и ЧаВо","back_home":"Назад в инбокс","fundamental":"Основные вопросы","technical":"Технологии и безопасность","q1":"Как долго хранятся письма?","a1":"Каждый адрес и каждое полученное письмо автоматически удаляются из нашей системы спустя ровно <b>60 минут</b>. Это гарантирует, что никакие старые данные не останутся на наших серверах для посторонних глаз.","q2":"Это бесплатно?","a2":"Да, DisposeMail — это всегда бесплатный инструмент, существующий за счет качественной рекламы для поддержки инфраструктуры.","q3":"Что такое DisposeMail?","a3":"DisposeMail — это утилита приватности для мгновенного создания временных email-адресов. Они защищают вас от спама и сбора данных сайтами.","q4":"Это законно?","a4":"Да. Использование временной почты — это законный и распространенный метод защиты приватности в сети.","q5":"Можно ли восстановить письма?","a5":"Нет. После удаления письма оно навсегда стирается из нашей оперативной памяти. Мы не храним бэкапов или архивов.","q6":"Зачем нужны свои домены?","a6":"Некоторые сайты блокируют обычные временные домены. Наш список позволяет обходить такие ограничения.","q7":"Поддерживает ли он вложения?","a7":"Да, наша система анализирует полный MIME-контент. Хотя мы стремимся сделать текст и HTML-контент читабельным, мы также позволяем вам полностью просматривать и обрабатывать структуры сообщений.","q8":"Это DisposeMail или DisposalMail?","a8":"Люди часто ищут <b>disposalmail</b>, <b>disposal temp mail</b>, <b>disposmail</b> или <b>dispose mail</b>. Вводите ли вы <b>disposalmail.com</b> или disposemail.xyz, вы ищете безопасную временную электронную почту. Мы официально DisposeMail, но мы предоставляем необходимые вам услуги \'disposal mail\'.","q9":"Нужно ли мне обновлять страницу, чтобы увидеть новые письма?","a9":"Нет! Наша <b>Zero-Loss архитектура</b> использует WebSockets в реальном времени. Как только электронное письмо попадает на наш сервер, оно мгновенно отправляется на экран вашего браузера без единого обновления.","q10":"Могу ли я восстановить адрес после истечения срока действия?","a10":"Абсолютно нет. Чтобы гарантировать вашу конфиденциальность, как только адрес или электронное письмо достигает 60-минутного предела (или вы нажимаете <b>Сжечь почту</b>), оно безвозвратно удаляется из нашей базы данных на основе оперативной памяти. У нас нет резервных копий.","q11":"Безопасно ли открывать вложения?","a11":"Несмотря на то, что мы анализируем и отображаем вложения, вам следует <b>всегда проявлять крайнюю осторожность</b> при открытии файлов от неизвестных отправителей. Мы рекомендуем загружать вложения только в том случае, если вы их явно ожидаете (например, счет-фактура или билет).","still_questions":"Остались вопросы?","support_desc":"Наша цель — лучший сервис временной почты. Если есть вопросы или идеи — мы здесь, чтобы помочь.","support_btn":"Поддержка по почте","create_btn":"Создать почту сейчас","secure_anon":"Безопасно и Анонимно","homepage_faq":"Частые вопросы"},"Steps":{"step1_title":"Создать","step1_desc":"Нажмите \'Новый\' для почты или введите свое имя.","step2_title":"Регистрация","step2_desc":"Используйте почту на любом сайте, для тестов или рассылок.","step3_title":"Получить","step3_desc":"Смотрите входящие в реальном времени с поддержкой HTML и вложений."},"UseCases":{"title":"Популярные случаи","case1_title":"1. Тестирование ПО и QA","case1_desc":"Разработчики используют разовые адреса для тестов без захламления реальных баз.","case2_title":"2. Скидки в магазинах","case2_desc":"Регистрируйтесь для купонов без подписки личной почты на ежедневный маркетинг.","case3_title":"3. Приватность на форумах","case3_desc":"Регистрируйтесь в сообществах, сохраняя личные данные в безопасности."},"Why":{"title":"Зачем нужна временная почта?","subtitle":"Узнайте, как DisposeMail защищает ваш цифровой след от нежелательных трекеров.","item1_title":"Защита от спама","item1_desc":"Хватит давать личную почту каждому сайту. Держите инбокс чистым от рекламного мусора.","item2_title":"Безопасность данных","item2_desc":"Утечки случаются ежедневно. С временным адресом ваша личность никогда не будет связана с сервисом.","item3_title":"Мгновенный доступ","item3_desc":"Без подтверждений и паролей. Ящик готов принимать коды за миллисекунды.","item4_title":"Множество доменов","item4_desc":"Переключайтесь между доменами, чтобы обходить фильтры и ограничения сайтов."},"About":{"title":"О проекте DisposeMail","back_inbox":"Назад в инбокс","mission_title":"Наша миссия","mission_desc":"В эпоху постоянной слежки и утечек данных проект <strong>DisposeMail</strong> был создан с единственной целью: защитить ваш основной почтовый ящик и вашу личность. Мы верим, что приватность — это фундаментальное право человека, а не роскошь. Наш сервис предоставляет временный щит между вами и внешним миром интернета, полным трекеров.","why_exist_title":"Почему мы существуем","why_exist_desc":"Каждый раз, когда вы подписываетесь на рассылку или приложение, вы рискуете раскрыть свой email спамерам и хакерам. Попав в \'список\', ваш адрес остается там навсегда. DisposeMail предоставляет мгновенный защитный буфер, позволяя вам пользоваться сетью без груза спама в будущем.","tech_title":"Наши технологии","tech_desc":"Мы используем современную облачную инфраструктуру, сети Cloudflare Edge и безопасные VPS для мгновенной доставки почты. В отличие от других, мы не храним ваши данные в постоянных базах. Наша WebSocket-архитектура обеспечивает показ писем на вашем экране в режиме реального времени.","commitment_title":"Приверженность приватности","item1":"<strong>Без логов:</strong> Мы не записываем IP-адреса и данные браузера.","item2":"<strong>Авто-очистка:</strong> Все данные безвозвратно удаляются каждые 60 минут.","item3":"<strong>Без регистрации:</strong> Нам не нужны ваши имя, телефон или настоящий email.","item4":"<strong>Шифрование:</strong> Весь трафик идет через SSL/TLS для максимальной безопасности.","transparency_title":"Прозрачность","transparency_desc":"Мы верим, что инструменты приватности должны быть открытыми. Если у вас есть вопросы о работе сервиса — пишите нам."},"Contact":{"title":"Свяжитесь с нами","subtitle":"Есть вопросы или идеи? Пишите нам, ответим в течение 24 часов.","business_title":"Бизнес-запросы","business_desc":"Партнерство, API или интеграции доменов.","quick_links":"Ссылки","faq":"Частые вопросы","api":"Документация API","blog":"Последние обновления","success_title":"Сообщение отправлено!","success_desc":"Спасибо за обращение. Мы получили ваш запрос.","send_another":"Отправить еще раз","name_label":"Полное имя","name_placeholder":"Иван Иванов","email_label":"Email адрес","email_placeholder":"ivan@example.com","message_label":"Сообщение","message_placeholder":"Чем мы можем помочь?","send_btn":"Отправить","error_msg":"Ошибка. Попробуйте снова или напишите нам прямо на почту."},"Privacy":{"title":"Политика конфиденциальности","back_inbox":"Назад в инбокс","sec1_title":"Обзор информации","sec1_desc":"В DisposeMail мы бережем вашу приватность. Мы не собираем имена, телефоны или любые личные данные.","sec2_title":"Хранение данных","sec2_desc":"Все письма и адреса удаляются через **60 минут**. Мы не храним бэкапов и архивных копий переданных данных.","sec3_title":"Куки и хранилище","sec3_desc":"Мы не используем следящие куки. Только технические сессионные данные для работы вашего временного адреса.","sec4_title":"Реклама","sec4_desc":"Мы показываем рекламу AdSense для работы сервиса. Партнеры могут использовать неличные данные для показа объявлений.","sec5_title":"Меры безопасности","sec5_desc":"Весь трафик зашифрован SSL/TLS. Инфраструктура защищена от несанкционированного доступа к вашим данным.","effective_date":"С: Январь 2024","verified":"Безопасность проверена"},"Terms":{"title":"Условия использования","back_inbox":"Назад в инбокс","sec1_title":"1. Принятие условий","sec1_desc":"Используя DisposeMail, вы соглашаетесь с данными условиями.","sec2_title":"2. Описание сервиса","sec2_desc":"DisposeMail предоставляет временные адреса. Мы не гарантируем 100% аптайм или вечное хранение данных.","sec3_title":"3. Запреты","sec3_desc":"Запрещено использовать сервис для спама или атак на нашу инфраструктуру.","sec4_title":"4. Ответственность","sec4_desc":"Мы не несем ответственности за потерю данных или ущерб от использования временной почты.","sec5_title":"5. Прекращение","sec5_desc":"Мы можем закрыть доступ любому пользователю, нарушающему данные правила.","sec6_title":"6. Изменения","sec6_desc":"Мы можем менять функции сервиса в любое время без предупреждения.","sec7_title":"7. Приватность","sec7_desc":"Ваше использование также регулируется Политикой конфиденциальности.","sec8_title":"8. Сторонние ссылки","sec8_desc":"Письма могут содержать ссылки на чужие сайты. Мы не отвечаем за их контент.","sec9_title":"9. Законодательство","sec9_desc":"Условия регулируются законами страны нашего присутствия.","sec10_title":"10. Контакты","sec10_desc":"Вопросы присылайте на support@disposemail.xyz.","last_updated":"Обновлено: Январь 2024"},"Footer":{"privacy":"Конфиденциальность","terms":"Условия использования","api":"API","faq":"ЧаВо","copyright":"© 2026 DisposeMail. Безопасно, анонимно, временно."},"Blog":{"title":"Новости приватности","subtitle":"Будьте в курсе последних трендов цифровой безопасности.","read_more":"Читать статью","back_all":"Назад в Блог","author_role":"Автор и Защитник Приватности","cta_title":"Защитите свой почтовый ящик сегодня.","cta_desc":"Перестаньте делиться своим настоящим адресом с каждым сайтом. Создайте свой первый временный адрес за считанные секунды.","cta_btn":"Создать Бесплатный Адрес","view_all":"Все статьи"}}'))}];

